function draw({svg,width,height,progress,params,state,controls}){
 const ns='http://www.w3.org/2000/svg', ink='#293841', muted='#68777d', teal='#007e80', gold='#bc7334', grid='#dde5e6';
 function el(id,tag,attrs,txt){let e=svg.querySelector('#'+id);if(!e){e=document.createElementNS(ns,tag);e.id=id;svg.appendChild(e);} for(const [k,v] of Object.entries(attrs||{}))e.setAttribute(k,v);if(txt!==undefined)e.textContent=txt;return e;}
 function t(id,x,y,txt,color=muted,size=13,anchor='start'){return el(id,'text',{x,y,fill:color,'font-size':size,'font-family':'sans-serif','text-anchor':anchor},txt);}
 function line(id,x1,y1,x2,y2,color=grid,dash=''){el(id,'line',{x1,y1,x2,y2,stroke:color,'stroke-width':1,'stroke-dasharray':dash});}
 const keys=[.4,1.3,2.3,3.5,4.6],values=[.6,3.6,1.1,3.2,.8],q=.3+4.4*progress;
 const raw=keys.map(k=>Math.exp(-.5*(q-k)**2)),z=raw.reduce((a,b)=>a+b,0),a=raw.map(v=>v/z),pred=a.reduce((s,v,i)=>s+v*values[i],0);
 const mobile=width<600, gap=mobile?0:56, left=42, pw=mobile?width-62:(width-112)/2;
 const upper={x:left,y:48,w:pw,h:mobile?142:204};const lower=mobile?{x:left,y:278,w:pw,h:112}:{x:left+pw+gap,y:48,w:pw,h:204};
 const X=v=>upper.x+upper.w*v/5,Y=v=>upper.y+upper.h*(1-v/4);
 t('head',left,22,'键的位置 → 权重 → 值的加权平均',ink,14);
 for(let i=0;i<=4;i++){line('yg'+i,upper.x,Y(i),upper.x+upper.w,Y(i));t('yt'+i,upper.x-10,Y(i)+4,String(i),muted,12,'end');}
 for(let i=0;i<=5;i++){t('xt'+i,X(i),upper.y+upper.h+19,String(i),muted,12,'middle');}
 line('xaxis',upper.x,Y(0),upper.x+upper.w,Y(0),muted);t('ylabel',upper.x-25,upper.y-10,'y',ink,13);t('xlabel',upper.x+upper.w,upper.y+upper.h+37,'位置 x',muted,12,'end');
 line('query',X(q),upper.y,X(q),Y(0),teal,'4 4');line('predguide',upper.x,Y(pred),X(q),Y(pred),teal,'3 4');
 for(let i=0;i<keys.length;i++){
  el('dot'+i,'circle',{cx:X(keys[i]),cy:Y(values[i]),r:5+10*a[i],fill:gold,'fill-opacity':.3+.7*a[i],stroke:gold,'stroke-width':1.5});
  t('key'+i,X(keys[i]),Y(values[i])-20,String(i+1),gold,12,'middle');
 }
 el('prediction','path',{d:`M ${X(q)} ${Y(pred)-7} l 7 7 l -7 7 l -7 -7 Z`,fill:teal,stroke:'#fff','stroke-width':1.5});
 t('readout',left, mobile?250:294,`查询 ${q.toFixed(2)}   →   预测 ${pred.toFixed(2)}`,teal,14);
 const BX=v=>lower.x+lower.w*v/5,BY=v=>lower.y+lower.h*(1-v);
 t('weights-title',lower.x,lower.y-12,'注意力 α（按键的位置排列）',ink,13);
 for(let v=0;v<=1;v+=.5){line('wg'+v,lower.x,BY(v),lower.x+lower.w,BY(v));t('wt'+v,lower.x-9,BY(v)+4,v.toFixed(1),muted,12,'end');}
 const bw=Math.min(28,lower.w*.07);
 for(let i=0;i<keys.length;i++){el('bar'+i,'rect',{x:BX(keys[i])-bw/2,y:BY(a[i]),width:bw,height:lower.h*a[i],rx:2,fill:teal});t('barlabel'+i,BX(keys[i]),BY(a[i])-7,(100*a[i]).toFixed(0)+'%',teal,12,'middle');t('keytick'+i,BX(keys[i]),BY(0)+18,String(i+1),gold,12,'middle');}
 t('sum',lower.x+lower.w,lower.y+lower.h+39,'Σα = 1 · 编号对应样本',muted,12,'end');
 return {example:'五个手选键值对；非原书随机样本',keys,values,query:q,rawKernel:raw,weights:a,weightSum:a.reduce((s,v)=>s+v,0),prediction:pred,convention:'w=1；softmax 沿键轴；高斯公共系数在归一化中抵消',range:'仅显示 x∈[0,5]；未执行模型训练'};
