function draw({svg,width,height,progress,params,state,controls}){
 const ns='http://www.w3.org/2000/svg',ink='#293841',muted='#68777d',teal='#007e80',gold='#bc7334',grid='#dde5e6';
 function el(id,tag,attrs,txt){let e=svg.querySelector('#'+id);if(!e){e=document.createElementNS(ns,tag);e.id=id;svg.appendChild(e);}for(const[k,v]of Object.entries(attrs||{}))e.setAttribute(k,v);if(txt!==undefined)e.textContent=txt;return e;}
 function t(id,x,y,txt,color=muted,size=13,anchor='start'){el(id,'text',{x,y,fill:color,'font-size':size,'font-family':'sans-serif','text-anchor':anchor},txt);}
 function line(id,x1,y1,x2,y2,color=grid,dash=''){el(id,'line',{x1,y1,x2,y2,stroke:color,'stroke-width':1,'stroke-dasharray':dash});}
 const keys=[.3,.85,1.35,1.9,2.45,2.9,3.45,4,4.65],noise=[-.3,.45,-.4,.3,-.5,.45,-.3,.35,-.2],values=keys.map((x,i)=>2*Math.sin(x)+x**.8+noise[i]),w=Number(params.w),q=2.5;
 function weights(x,s){const logits=keys.map(k=>-.5*((x-k)*s)**2),m=Math.max(...logits),r=logits.map(v=>Math.exp(v-m)),z=r.reduce((a,b)=>a+b,0);return r.map(v=>v/z);}
 function predict(x,s){return weights(x,s).reduce((v,a,i)=>v+a*values[i],0);}
 const mobile=width<600, x0=42, cw=width-64, top=57, ph=mobile?158:184, base=top+ph, X=x=>x0+cw*x/5,Y=y=>top+ph*(5-y)/6;
 t('top',x0,20,`手选 w = ${w.toFixed(2)}`,teal,14);
 t('bw',width-22,20,w===0?'等权平均':`有效宽度 1/|w| = ${(1/w).toFixed(2)}`,muted,12,'end');
 t('legend-current',x0,42,'— 当前预测',teal,12);t('legend-ref',x0+106,42,'┄ w = 1',muted,12);t('legend-sample',x0+182,42,'○ 固定样本',gold,12);
 for(let y=-1;y<=5;y++){line('grid'+y,x0,Y(y),x0+cw,Y(y));t('y'+y,x0-10,Y(y)+4,String(y),muted,12,'end');}
 for(let x=0;x<=5;x++)t('x'+x,X(x),base+18,String(x),muted,12,'middle');
 t('ylab',x0-25,top-3,'y',ink);t('xlab',x0+cw,base+35,'位置 x',muted,12,'end');
 const curve=s=>Array.from({length:201},(_,i)=>{const x=i/40;return `${i?'L':'M'}${X(x).toFixed(2)},${Y(predict(x,s)).toFixed(2)}`;}).join(' ');
 el('reference','path',{d:curve(1),fill:'none',stroke:muted,'stroke-width':1.8,'stroke-dasharray':'5 5'});
 el('current','path',{d:curve(w),fill:'none',stroke:teal,'stroke-width':2.7});
 for(let i=0;i<keys.length;i++)el('point'+i,'circle',{cx:X(keys[i]),cy:Y(values[i]),r:4,fill:'#fff',stroke:gold,'stroke-width':1.5});
 const a=weights(q,w),py=predict(q,w);
 line('qline',X(q),top,X(q),base,teal,'3 4');el('out','circle',{cx:X(q),cy:Y(py),r:5,fill:teal});
 const barTop=base+72,bh=mobile?85:92,barBase=barTop+bh,by=v=>barBase-bh*v;
 t('barhead',x0,barTop-17,`同一查询 x = 2.50 · 预测 ${py.toFixed(2)}`,teal,13);
 for(let v=0;v<=1;v+=.5){line('bg'+v,x0,by(v),x0+cw,by(v));t('bt'+v,x0-10,by(v)+4,v.toFixed(1),muted,12,'end');}
 const bw=Math.min(25,cw*.055);
 for(let i=0;i<keys.length;i++)el('weight'+i,'rect',{x:X(keys[i])-bw/2,y:by(a[i]),width:bw,height:bh*a[i],rx:2,fill:teal});
 for(let x=0;x<=5;x++)t('bk'+x,X(x),barBase+17,String(x),muted,12,'middle');
 t('barx',x0+cw,barBase+35,'键的位置 xᵢ',muted,12,'end');t('bara',x0,barBase+35,'α · Σα = 1',muted,12);
 return {example:'九个固定样本；噪声偏移手选，非正态随机抽样',keys,values,noiseOffsets:noise,w,query:q,weights:a,weightSum:a.reduce((s,v)=>s+v,0),prediction:py,effectiveBandwidth:w===0?null:1/Math.abs(w),convention:'exp(-((x-xᵢ)w)²/2)，softmax 沿键轴；w=0 为等权，±w 相同',range:'w∈[0,6]；手选参数未训练；不推断泛化性能'};
}
